import { Router, type Request, type Response, type NextFunction } from 'express';
import { signJwt, verifyJwt, type JwtClaims } from './lib/jwt.ts';
import { checkRateLimit } from './rate-limit.ts';
import { findUserByEmail, listInvoices, listSubscriptions } from './store.ts';
import { nonEmptyString, requireBody } from './validate.ts';

export const router = Router();

type AuthedRequest = Request & { user?: JwtClaims };

router.post('/login', requireBody({ email: nonEmptyString, password: nonEmptyString }), (req: Request, res: Response) => {
  const { email, password } = req.body as { email: string; password: string };
  const user = findUserByEmail(email);
  if (!user || user.password !== password) {
    return res.status(401).json({ error: 'Invalid email or password' });
  }
  return res.json({ token: signJwt({ sub: user.id, role: user.role }) });
});

router.get('/me', (req: AuthedRequest, res: Response) => {
  const token = req.headers.authorization?.replace(/^Bearer /, '');
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  try {
    req.user = verifyJwt(token);
  } catch (error) {
    return res.status(401).json({ error: (error as Error).message });
  }
  return res.json({ id: req.user.sub, role: req.user.role });
});

router.get('/subscriptions', (req: AuthedRequest, res: Response) => {
  const token = req.headers.authorization?.replace(/^Bearer /, '');
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  try {
    req.user = verifyJwt(token);
  } catch (error) {
    return res.status(401).json({ error: (error as Error).message });
  }
  if (!checkRateLimit(req.user.sub, 'read')) return res.status(429).json({ error: 'Too many requests' });
  return res.json(listSubscriptions(req.user.sub));
});

router.get('/invoices', (req: AuthedRequest, res: Response) => {
  const token = req.headers.authorization?.replace(/^Bearer /, '');
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  try {
    req.user = verifyJwt(token);
  } catch (error) {
    return res.status(401).json({ error: (error as Error).message });
  }
  if (!checkRateLimit(req.user.sub, 'read')) return res.status(429).json({ error: 'Too many requests' });
  return res.json(listInvoices(req.user.sub));
});

router.post('/subscriptions/:id/cancel', (req: AuthedRequest, res: Response, next: NextFunction) => {
  const token = req.headers.authorization?.replace(/^Bearer /, '');
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  try {
    req.user = verifyJwt(token);
  } catch (error) {
    return res.status(401).json({ error: (error as Error).message });
  }
  if (!checkRateLimit(req.user.sub, 'write')) return res.status(429).json({ error: 'Too many requests' });
  const subscription = listSubscriptions(req.user.sub).find((entry) => entry.id === req.params.id);
  if (!subscription) return next();
  subscription.status = 'cancelled';
  return res.json(subscription);
});

import type { Request, Response, NextFunction } from 'express';

export interface FieldError {
  field: string;
  message: string;
}

export type FieldRule = (value: unknown) => string | undefined;

export type BodySchema = Record<string, FieldRule>;

export const nonEmptyString: FieldRule = (value) =>
  typeof value === 'string' && value !== '' ? undefined : 'must be a non-empty string';

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function validateBody(body: unknown, schema: BodySchema): FieldError[] {
  if (!isPlainObject(body)) return [{ field: 'body', message: 'must be a JSON object' }];
  const errors: FieldError[] = [];
  for (const [field, rule] of Object.entries(schema)) {
    const message = rule(body[field]);
    if (message) errors.push({ field, message });
  }
  return errors;
}

export function requireBody(schema: BodySchema) {
  return (req: Request, res: Response, next: NextFunction) => {
    const fields = validateBody(req.body, schema);
    if (fields.length > 0) return res.status(400).json({ error: 'Invalid request body', fields });
    return next();
  };
}

import type { Server } from 'node:http';
import type { AddressInfo } from 'node:net';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { createApp } from '../server/app.ts';

let server: Server;
let baseUrl: string;

beforeAll(async () => {
  server = createApp().listen(0);
  await new Promise((resolve) => server.once('listening', resolve));
  baseUrl = `http://localhost:${(server.address() as AddressInfo).port}/api`;
});

afterAll(() => new Promise((resolve) => server.close(resolve)));

function postLogin(body: string | undefined, headers: Record<string, string> = { 'content-type': 'application/json' }) {
  return fetch(`${baseUrl}/login`, { method: 'POST', headers, body });
}

describe('POST /login body validation', () => {
  it('rejects a request with no JSON body', async () => {
    const response = await postLogin(undefined, {});
    expect(response.status).toBe(400);
    expect(await response.json()).toEqual({
      error: 'Invalid request body',
      fields: [{ field: 'body', message: 'must be a JSON object' }],
    });
  });

  it('names every field with the wrong type', async () => {
    const response = await postLogin(JSON.stringify({ email: 123, password: null }));
    expect(response.status).toBe(400);
    const json = await response.json();
    expect(json.fields.map((entry: { field: string }) => entry.field)).toEqual(['email', 'password']);
  });

  it('names only the field that failed', async () => {
    const response = await postLogin(JSON.stringify({ email: 'ada@example.com', password: '' }));
    expect(response.status).toBe(400);
    expect((await response.json()).fields).toEqual([{ field: 'password', message: 'must be a non-empty string' }]);
  });

  it('rejects a JSON array body', async () => {
    const response = await postLogin(JSON.stringify([{ email: 'ada@example.com', password: 'hunter2' }]));
    expect(response.status).toBe(400);
    expect((await response.json()).fields).toEqual([{ field: 'body', message: 'must be a JSON object' }]);
  });

  it('returns JSON for malformed JSON', async () => {
    const response = await postLogin('{"email": ');
    expect(response.status).toBe(400);
    expect(await response.json()).toEqual({
      error: 'Invalid request body',
      fields: [{ field: 'body', message: 'must be valid JSON' }],
    });
  });

  it('leaves the oversized-body status alone', async () => {
    const response = await postLogin(JSON.stringify({ email: 'a@example.com', password: 'x'.repeat(200_000) }));
    expect(response.status).toBe(413);
  });

  it('still logs in with a valid body', async () => {
    const response = await postLogin(JSON.stringify({ email: 'bea@example.com', password: 'hunter2' }));
    expect(response.status).toBe(200);
    expect(typeof (await response.json()).token).toBe('string');
  });

  it('still returns 401 for wrong credentials', async () => {
    const response = await postLogin(JSON.stringify({ email: 'bea@example.com', password: 'wrong' }));
    expect(response.status).toBe(401);
  });
});
